referenceSolutions.javascript:
export function solve(initial, actions) {
  let state = initial;
  return actions.map((action) => {
    if (action.type === "add") state += action.value;
    else if (action.type === "set") state = action.value;
    else if (action.type === "reset") state = initial;
    return state;
  });
}

